import re, subprocess
def fix_boundary():
    p = "constant/polyMesh/boundary"
    s = open(p).read()
    s = s.replace("""    frontAndBack
    {
        type            patch;
        physicalType    patch;""", """    frontAndBack
    {
        type            empty;
        physicalType    empty;""")
    s = s.replace("""    walls
    {
        type            patch;
        physicalType    patch;""", """    walls
    {
        type            wall;
        physicalType    wall;""")
    open(p,"w").write(s)
fix_boundary()
r = subprocess.run(["checkMesh"], capture_output=True, text=True)
print(r.stdout[-2500:])

